CREATE DATABASE IF NOT EXISTS perpustakaan CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE perpustakaan;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,nis VARCHAR(30) NULL,class_name VARCHAR(50) NULL,role VARCHAR(20) NOT NULL DEFAULT 'siswa',email_verified_at TIMESTAMP NULL,password VARCHAR(255) NOT NULL,remember_token VARCHAR(100) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL);
CREATE TABLE books (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,author VARCHAR(150) NOT NULL,publisher VARCHAR(150) NOT NULL,year INT NOT NULL,stock INT NOT NULL DEFAULT 0,description TEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL);
CREATE TABLE loans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,book_id BIGINT UNSIGNED NOT NULL,borrow_date DATE NOT NULL,due_date DATE NOT NULL,return_date DATE NULL,status VARCHAR(30) NOT NULL DEFAULT 'dipinjam',notes TEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,CONSTRAINT loans_user_fk FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT loans_book_fk FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE RESTRICT);
